890-8711","data_nascimento":"1992-07-02","data_matricula":"2026-01-23","endereco":"POVOADO AREA BRANCA","bairro":"AREA RURAL","cidade":"PACATUBA","uf":"SE","cep":"49970000","sexo":"F","rg":"09.567.561-2","orgao_emissor":"SSP/SE","rg_uf_emissao":"SE","tipo_documento":"RG (ANTIGO)","nome_mae":"NEURACI BRUNO MENEZES","nome_pai":"JINALDO MENEZES","nacionalidade":"BRASILEIRA","naturalidade":null}]$source$::jsonb;
  v_turma public.turmas%rowtype;
  v_row record;
  v_parceiro_id uuid;
begin
  if jsonb_array_length(v_source) <> 60 then
    raise exception 'A importação T43 exige exatamente 60 registros de origem.';
  end if;

  perform pg_advisory_xact_lock(hashtext('importacao-enf-t43-20260726'));

  select *
  into v_turma
  from public.turmas
  where codigo = 'ENF-T43-INT-MAT'
  for update;

  if not found then
    raise exception 'Turma ENF-T43-INT-MAT não encontrada.';
  end if;

  for v_row in
    select *
    from jsonb_to_recordset(v_source) as s(
      linha integer,
      turma_origem text,
      nome text,
      cpf text,
      email text,
      telefone text,
      data_nascimento date,
      data_matricula date,
      endereco text,
      bairro text,
      cidade text,
      uf text,
      cep text,
      sexo text,
      rg text,
      orgao_emissor text,
      rg_uf_emissao text,
      tipo_documento text,
      nome_mae text,
      nome_pai text,
      nacionalidade text,
      naturalidade text,
      certidao_tipo text,
      certidao_modelo text,
      certidao_matricula text,
      certidao_termo text,
      certidao_livro text,
      certidao_folha text
    )
    order by linha
  loop
    v_parceiro_id := null;

    select p.id
    into v_parceiro_id
    from public.parceiros p
    where regexp_replace(coalesce(p.cpf_cnpj, ''), '\\D', '', 'g') = v_row.cpf
    order by p.created_at, p.id
    limit 1;

    if v_parceiro_id is null then
      insert into public.parceiros (
        tipo,
        nome,
        cpf_cnpj,
        email,
        telefone,
        cep,
        endereco,
        bairro,
        cidade,
        uf,
        polo_id,
        status,
        observacao,
        data_nascimento,
        sexo,
        rg,
        orgao_emissor,
        nacionalidade,
        naturalidade,
        nome_mae,
        nome_pai,
        rg_uf_emissao,
        tipo_documento,
        certidao_tipo,
        certidao_modelo,
        certidao_matricula,
        certidao_termo,
        certidao_livro,
        certidao_folha
      ) values (
        'Aluno',
        v_row.nome,
        v_row.cpf,
        v_row.email,
        v_row.telefone,
        v_row.cep,
        v_row.endereco,
        v_row.bairro,
        v_row.cidade,
        v_row.uf,
        v_turma.polo_id,
        'ATIVO',
        'Importado de turma43.xls sem criação de usuário Auth e sem financeiro.',
        v_row.data_nascimento,
        v_row.sexo,
        v_row.rg,
        v_row.orgao_emissor,
        coalesce(v_row.nacionalidade, 'BRASILEIRA'),
        v_row.naturalidade,
        v_row.nome_mae,
        v_row.nome_pai,
        v_row.rg_uf_emissao,
        v_row.tipo_documento,
        v_row.certidao_tipo,
        v_row.certidao_modelo,
        v_row.certidao_matricula,
        v_row.certidao_termo,
        v_row.certidao_livro,
        v_row.certidao_folha
      )
      returning id into v_parceiro_id;
    end if;

    if not exists (
      select 1
      from public.matriculas m
      where m.aluno_id = v_parceiro_id
        and m.turma_id = v_turma.id
    ) then
      perform internal_academic.authorize_enrollment_upsert(
        v_parceiro_id,
        v_turma.id,
        'PENDENTE'
      );

      insert into public.matriculas (
        aluno_id,
        turma_id,
        status,
        data_matricula,
        financeiro_herdado,
        gerar_cobranca_inicial,
        gerar_cobranca_futura,
        sincronizar_asaas
      ) values (
        v_parceiro_id,
        v_turma.id,
        'PENDENTE',
        v_row.data_matricula::timestamp at time zone 'America/Maceio',
        false,
        false,
        false,
        false
      );
    end if;
  end loop;

  update public.turmas t
  set vagas_totais = greatest(
    t.vagas_totais,
    (select count(*)::integer from public.matriculas m where m.turma_id = t.id)
  )
  where t.id = v_turma.id;
end;
